// Its own project, because the generator runs on TypeScript 6's compiler API and the workspace is on TypeScript 7.
export default {
  input: "../../.oas/api.json",
  // The workspace compiles with exactOptionalPropertyTypes, which the generated client is not written for.
  output: {
    path: "../../apps/web/src/lib/api/generated",
    header: [
      "// @ts-nocheck",
      "// Generated by @hey-api/openapi-ts from .oas/api.json; run `bun run api:generate` in apps/web."
    ]
  },
  plugins: [
    "@hey-api/typescript",
    // The console is served from the API's origin, so requests stay relative and carry the session cookie.
    { name: "@hey-api/client-fetch", baseUrl: false, throwOnError: true },
    "@hey-api/sdk",
    { name: "@tanstack/react-query", infiniteQueryOptions: false }
  ]
}
